.dm-ccx-cur{display:flex;align-items:center;gap:6px;height:34px;padding:0 10px;border-radius:10px;background:var(--dm-surface);box-shadow:0 1px 2px rgba(0,0,0,.06);font-size:13px;font-weight:500}
