.dm-ccx-sw:hover{color:var(--dm-fg)}
.dm-ccx-sw.dm-go{transform:rotate(180deg)}
.dm-ccx-rate{font-size:12px;text-align:center;margin-top:4px;display:flex;align-items:center;justify-content:center;gap:6px}
.dm-ccx-rate .dm-dot{color:var(--dm-ok);animation:dm-ccpulse 2s ease-in-out infinite}
@keyframes dm-ccpulse{50%{opacity:.4}}
.dm-ccx .dm-pop{min-width:180px}
.dm-ccx .dm-mi .dm-cd{font-family:var(--dm-mono);font-size:11.5px;color:var(--dm-muted);width:32px}

